/// <summary>
/// PricingAttribute of table <c>InventModelGroupItem</c> field ModelGroupId.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(InventModelGroupItem, ModelGroupId))]
internal class GUPPricingAttributeInventModelGroupItemModelGroupId extends GUPPricingAttributeInventModelGroupItem implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventModelGroupItem, ModelGroupId);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    InventModelGroupItem    inventModelGroupItem;
    InventModelGroup        inventModelGroup;
    InventTable             inventTable;

    while select ModelGroupId, ModelGroupDataAreaId, ItemId, ItemDataAreaId from inventModelGroupItem
        join ModelGroupId, DataAreaId, Name from InventModelGroup
          group by InventModelGroup.ModelGroupId, InventModelGroup.DataAreaId, InventModelGroup.Name
          where InventModelGroup.ModelGroupId == InventModelGroupItem.ModelGroupId
            && inventModelGroup.DataAreaId == InventModelGroupItem.ModelGroupDataAreaId             
        join ItemId, DataAreaId from inventTable
        where inventTable.ItemId == inventModelGroupItem.ItemId
            && inventTable.DataAreaId == inventModelGroupItem.ItemDataAreaId  
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(InventModelGroup.ModelGroupId, InventModelGroup.Name );
        ret.add(valueObject);
    }
    return ret;
}
